insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('578', '뜨또', 'Tteu-tto', 'yaminjeongeum', null, '팔에 새긴 한글 문신 ''비버''를 돌려 읽은 저스틴 비버의 별명', '{"de": "Justin Bieber, benannt nach dem quer gelesenen Hangul-Tattoo auf seinem Arm", "en": "Justin Bieber, nicknamed after reading his Hangul arm tattoo sideways", "es": "Justin Bieber, apodado al leer de lado su tatuaje en hangul", "ja": "腕のハングルタトゥー「비버」を回して読んだジャスティン・ビーバーのあだ名", "vi": "Biet danh cua Justin Bieber tu viec doc nghieng hinh xam Hangul tren tay anh"}'::jsonb, '[뜨또]', '[{"definition": "캐나다 가수 저스틴 비버를 가리키는 인터넷 별명. 2014년 그가 팔에 ''비버''라는 한글 문신을 세로로 눕혀 새겼는데, 사진 속 글자를 90도 돌려 읽으니 ''뜨또''로 보인다는 것을 누리꾼들이 발견하면서 붙었다. 글자를 돌려 읽는 야민정음 회전형이 실제 사진에서 우연히 생겨난 사례다.", "definition_i18n": {"de": "Ein Internet-Spitzname fur den kanadischen Sanger Justin Bieber. 2014 liess er sich 비버 (Bieber) quer auf den Arm tatowieren, und koreanische Nutzer bemerkten, dass das um neunzig Grad gedrehte Foto die Buchstaben zu 뜨또 macht. Ein Fall, in dem der Rotationstyp des Yaminjeongeum zufallig auf einem echten Foto entstand.", "en": "An internet nickname for the Canadian singer Justin Bieber. In 2014 he had 비버 (Bieber) tattooed on his arm running sideways, and Korean users noticed that rotating the photo ninety degrees turns the letters into 뜨또. It is a case of the rotation type of Yaminjeongeum happening by accident in a real photograph.", "es": "Apodo de internet para el cantante canadiense Justin Bieber. En 2014 se tatuo 비버 (Bieber) en el brazo de lado, y los internautas coreanos vieron que girando la foto noventa grados las letras se leen 뜨또. Es un caso en que el tipo rotacion del yaminjeongeum surgio por azar en una foto real.", "ja": "カナダの歌手ジャスティン・ビーバーを指すネットのあだ名。2014年に腕へ「비버」というハングルタトゥーを横倒しに入れたところ、写真の字を90度回すと「뜨또」に見えるとネットユーザーが気づいて付いた。字を回して読む野民正音の回転型が実際の写真で偶然生まれた例。", "vi": "Biet danh tren mang cua ca si nguoi Canada Justin Bieber. Nam 2014 anh xam chu 비버 (Bieber) nam ngang tren canh tay, va cu dan mang Han Quoc phat hien xoay anh chin muoi do thi chu thanh 뜨또. Day la truong hop kieu quay cua yaminjeongeum xuat hien tinh co trong mot buc anh that."}, "examples": [{"de": "Die Tickets fur das Tteu-tto-Konzert in Korea kommen raus.", "eng": "Tickets for the Tteu-tto concert in Korea are opening.", "es": "Salen las entradas del concierto de Tteu-tto en Corea.", "ja": "トゥットの来韓公演のチケット出るって。", "kor": "뜨또 내한 공연 티켓 열린대.", "vi": "Sap mo ban ve show cua Tteu-tto o Han Quoc do."}, {"de": "Dreh das Tattoo-Foto und es liest sich wirklich Tteu-tto haha.", "eng": "Rotate the tattoo photo and it really does read Tteu-tto lol.", "es": "Giras la foto del tatuaje y de verdad se lee Tteu-tto jaja.", "ja": "タトゥーの写真回したらマジでトゥットって読めるwww", "kor": "문신 사진 돌려 보니까 진짜 뜨또로 읽히네ㅋㅋ", "vi": "Xoay anh hinh xam thi doc ra Tteu-tto that hihi."}], "type": "명사"}]'::jsonb, '2014년 3월 저스틴 비버가 한글로 ''비버''를 새긴 문신 사진이 공개됐는데, 글자가 팔을 따라 옆으로 누운 방향이라 사진을 90도 돌리면 ''뜨또''처럼 읽혔다. 이를 발견한 누리꾼들이 별명으로 굳혔고, 언론도 ''뜨또가 누구야''라는 식으로 보도했다. 야민정음의 회전형 사례를 설명할 때 자주 함께 인용된다.', '{"de": "Im Marz 2014 wurde das Foto von Justin Biebers Hangul-Tattoo 비버 veroffentlicht; die Zeichen liegen quer am Arm, also liest sich das um neunzig Grad gedrehte Bild als 뜨또. Nutzer, die das bemerkten, machten daraus einen Spitznamen, und die Presse fragte in Schlagzeilen, wer 뜨또 sei. Es wird regelmassig zitiert, wenn der Rotationstyp des Yaminjeongeum erklart wird.", "en": "In March 2014 a photo of Justin Bieber''s Hangul tattoo reading 비버 went public; the letters lie sideways along his arm, so rotating the image ninety degrees makes them read 뜨또. Korean users who spotted this turned it into a nickname, and the press ran headlines asking who 뜨또 was. It is regularly cited when explaining the rotation type of Yaminjeongeum.", "es": "En marzo de 2014 se publico la foto del tatuaje en hangul de Justin Bieber, 비버; las letras van de lado por el brazo, asi que girar la imagen noventa grados las convierte en 뜨또. Los internautas que lo vieron lo fijaron como apodo y la prensa titulo preguntando quien era 뜨또. Se cita a menudo al explicar el tipo rotacion del yaminjeongeum.", "ja": "2014年3月、ジャスティン・ビーバーがハングルで「비버」と入れたタトゥーの写真が公開されたが、字が腕に沿って横倒しだったため写真を90度回すと「뜨또」と読めた。気づいたネットユーザーがあだ名として定着させ、メディアも「뜨또って誰」と報じた。野民正音の回転型を説明する際によく引かれる。", "vi": "Thang 3 nam 2014 buc anh hinh xam Hangul 비버 cua Justin Bieber duoc cong bo; chu nam ngang doc theo canh tay, nen xoay anh chin muoi do thi doc thanh 뜨또. Cu dan mang phat hien dieu nay bien no thanh biet danh, va bao chi con giat tit hoi 뜨또 la ai. No thuong duoc dan khi giai thich kieu quay cua yaminjeongeum."}'::jsonb, '팬들끼리 가볍게 부르는 별명이라 악의는 거의 없지만, 문신을 놀린 데서 시작한 말이라 본인 앞이나 공식 자리에서는 쓰지 않는다. 어느 쪽으로 적어도 같은 사람을 가리킨다 — 순서를 뒤집은 ''또뜨''도 같은 말이다.', '{"de": "Fans nutzen es locker und selten boshaft, doch es begann als Scherz uber sein Tattoo - also nicht in offiziellen Kontexten und nicht ihm gegenuber. Beide Schreibungen meinen dieselbe Person; das umgedrehte 또뜨 ist dasselbe Wort.", "en": "Fans use it lightly and it is rarely malicious, but it started as a joke about his tattoo, so it stays out of official contexts and away from the man himself. Both spellings mean the same person - the flipped 또뜨 is the same word.", "es": "Los fans lo usan a la ligera y rara vez con malicia, pero nacio como broma sobre su tatuaje, asi que no se usa en contextos oficiales ni delante de el. Ambas grafias designan a la misma persona: 또뜨, con el orden invertido, es la misma palabra.", "ja": "ファン同士が軽く呼ぶあだ名で悪意はほぼないが、タトゥーをからかったのが始まりなので本人の前や公式の場では使わない。どちらの表記も同じ人を指す — 順を入れ替えた「또뜨」も同じ語。", "vi": "Fan dung nhe nhang va hiem khi ac y, nhung no bat dau tu viec dua ve hinh xam, nen khong dung trong boi canh chinh thuc hay truoc mat anh ay. Ca hai cach viet deu chi mot nguoi - 또뜨 dao thu tu cung la tu nay."}'::jsonb, '{"롬곡","세종머앟","댕댕이"}'::text[], '{"또뜨"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Justin Bieber (nickname from his rotated tattoo)"}, {"lang": "🇯🇵 JA", "text": "ジャスティン・ビーバー(回したタトゥー由来のあだ名)"}, {"lang": "🇨🇳 ZH", "text": "贾斯汀·比伯(旋转纹身而来的绰号)"}, {"lang": "🇻🇳 VI", "text": "Justin Bieber (biet danh tu hinh xam xoay nguoc)"}, {"lang": "🇪🇸 ES", "text": "Justin Bieber (apodo por su tatuaje girado)"}, {"lang": "🇩🇪 DE", "text": "Justin Bieber (Spitzname vom gedrehten Tattoo)"}]'::jsonb),
('579', '띵언', 'Tting-eon', 'yaminjeongeum', null, '''명언''을 모양이 닮은 글자로 바꿔 쓴 야민정음', '{"de": "''Weisheit'' mit einer ahnlich aussehenden Silbe geschrieben", "en": "''Wise saying'' respelled with a look-alike syllable", "es": "''Frase celebre'' reescrita con una silaba parecida", "ja": "「名言」を形の似た字に変えた野民正音", "vi": "''Danh ngon'' viet lai bang am tiet trong giong"}'::jsonb, '[띵언]', '[{"definition": "''명언(名言)''을 야민정음으로 적은 말. 글자 크기를 키우면 ''명''이 ''띵''처럼 보인다는 점을 이용한 자모 치환형이다. 교과서에 나올 법한 위인의 명언보다는, 친구가 툭 던진 웃긴 한마디나 예능·드라마의 뼈 때리는 대사를 반쯤 장난스럽게 치켜세울 때 쓴다.", "definition_i18n": {"de": "Yaminjeongeum-Schreibung von 명언, einem beruhmten Ausspruch. Vergrossert man die Schrift, sieht 명 aus wie 띵 - dieser Formtausch ist der ganze Trick. Es meint selten ein echtes historisches Zitat, sondern kront den witzigen Spruch eines Freundes oder einen schonungslos wahren Satz aus Show oder Drama, immer augenzwinkernd.", "en": "Yaminjeongeum spelling of 명언, a famous saying. Blow the font up and 명 starts to look like 띵 - that shape swap is the whole trick. It rarely means a real historical quote; it crowns a friend''s funny throwaway line or a brutally true line from a variety show or drama, always with a wink.", "es": "Escritura yaminjeongeum de 명언, una frase celebre. Al agrandar la letra, 명 se parece a 띵: ese cambio de forma es todo el truco. Rara vez designa una cita historica; corona la ocurrencia graciosa de un amigo o una frase demoledora de un programa o un drama, siempre con guino.", "ja": "「名言(명언)」を野民正音で書いた語。字を大きくすると「명」が「띵」に見えることを利用した字母置換型。偉人の名言というより、友達がぽろっと言った面白い一言やバラエティ・ドラマの刺さるセリフを半分ふざけて持ち上げるときに使う。", "vi": "Cach viet yaminjeongeum cua 명언, danh ngon. Phong to chu len thi 명 trong giong 띵 - do la toan bo tro nay. No hiem khi chi mot cau noi lich su; no tan boc cau dua vui cua ban be hay cau thoai dau don trong show hoac phim, luon co net dua."}, "examples": [{"de": "Das ist echt ein Tting-eon - ich hab es gescreenshottet.", "eng": "That is a straight-up tting-eon - I screenshotted it.", "es": "Eso es un tting-eon de verdad, le hice captura.", "ja": "これガチでティンオンだわ、スクショした。", "kor": "이거 진짜 띵언이다, 캡처해 놨어.", "vi": "Cau nay dung la tting-eon, tui chup man hinh roi."}, {"de": "Der Lehrer hat heute noch ein Tting-eon dagelassen haha.", "eng": "Teacher dropped one tting-eon on the way out lol.", "es": "El profe solto un tting-eon antes de irse jaja.", "ja": "先生が今日ティンオン一つ残して帰ったwww", "kor": "쌤이 오늘 띵언 하나 남기고 가셨음ㅋㅋ", "vi": "Thay hom nay de lai mot cau tting-eon roi di luon hihi."}], "type": "명사"}]'::jsonb, '야민정음은 디시인사이드 국내야구 갤러리(''야갤'')에서 자란 표기 놀이로, ''야갤''과 ''훈민정음''을 합친 이름이다. 모양이 닮은 자모로 바꾸기, 글자 돌리기, 압축하기 등 방식이 여럿인데 ''명→띵''은 가장 널리 퍼진 치환 규칙이다. 같은 규칙에서 띵작(명작), 띵곡(명곡), 띵문대(명문대), 띵품(명품)이 나왔고 띵언도 그중 하나다.', '{"de": "Yaminjeongeum ist ein Umschreibspiel aus DCInsides Galerie fur heimischen Baseball (''Yagal''); der Name mischt Yagal und Hunminjeongeum. Es tauscht ahnlich aussehende Buchstaben, dreht Zeichen, staucht sie und mehr, und 명 zu 띵 ist die verbreitetste Tauschregel. Dieselbe Regel brachte 띵작 (Meisterwerk), 띵곡 (grossartiger Song), 띵문대 (Eliteuni) und 띵품 (Luxusware) hervor; 띵언 gehort dazu.", "en": "Yaminjeongeum is a respelling game that grew out of DCInside''s domestic-baseball gallery (''Yagal''); the name blends Yagal with Hunminjeongeum. It swaps look-alike letters, rotates characters, compresses them and more, and 명 to 띵 is its most widespread swap rule. The same rule produced 띵작 (masterpiece), 띵곡 (great song), 띵문대 (elite university) and 띵품 (luxury goods); 띵언 is one of that family.", "es": "El yaminjeongeum es un juego de reescritura surgido de la galeria de beisbol nacional de DCInside (''Yagal''); el nombre mezcla Yagal con Hunminjeongeum. Cambia letras parecidas, gira caracteres, los comprime y mas, y 명 por 띵 es su regla de cambio mas extendida. De la misma regla salieron 띵작 (obra maestra), 띵곡 (cancion buenisima), 띵문대 (universidad de elite) y 띵품 (articulos de lujo); 띵언 pertenece a esa familia.", "ja": "野民正音はDCインサイド国内野球ギャラリー(「野ギャル」)で育った表記遊びで、「野ギャル」と「訓民正音」を合わせた名。似た字母への置換、回転、圧縮など方式があり、「명→띵」は最も広まった置換規則。同じ規則から띵작(名作)、띵곡(名曲)、띵문대(名門大)、띵품(名品)が生まれ、띵언もその一つ。", "vi": "Yaminjeongeum la tro viet lai lon len tu gallery bong chay noi dia cua DCInside (''Yagal''); ten ghep Yagal voi Hunminjeongeum. No doi chu cai trong giong, quay chu, nen chu..., va 명 thanh 띵 la quy tac doi pho bien nhat. Cung quy tac do sinh ra 띵작 (kiet tac), 띵곡 (bai hat hay), 띵문대 (dai hoc danh tieng) va 띵품 (hang hieu); 띵언 thuoc ho do."}'::jsonb, '댓글·DM·SNS 같은 가벼운 글에서만 쓴다. 과제나 이메일에 쓰면 어색하다. 칭찬이지만 격식 있는 칭찬은 아니고, ''와 띵언이다''처럼 감탄사와 붙여 쓰는 경우가 많다.', '{"de": "Nur fur Kommentare, DMs und Social Posts - in einer Hausarbeit oder Mail wirkt es falsch. Es ist Lob, aber kein formelles, und laeuft meist mit einem Ausruf mit: 와 띵언이다 (wow, ein Tting-eon).", "en": "Keep it to comments, DMs and social posts - it reads wrong in an assignment or an email. It is praise, but not respectful praise, and it usually rides along with an interjection, as in 와 띵언이다 (whoa, that is a tting-eon).", "es": "Resérvalo para comentarios, mensajes y redes; en un trabajo o un correo suena mal. Es un elogio, pero no formal, y suele ir con una interjeccion: 와 띵언이다 (vaya, menudo tting-eon).", "ja": "コメントやDM、SNSなど軽い文でのみ使う。課題やメールでは浮く。褒め言葉だが格式ある褒め方ではなく、「와 띵언이다」のように感嘆詞と一緒に使うことが多い。", "vi": "Chi dung trong binh luan, tin nhan va mang xa hoi; viet vao bai tap hay email thi lac long. Do la loi khen nhung khong trang trong, va thuong di kem than tu nhu 와 띵언이다 (chao oi, tting-eon that)."}'::jsonb, '{"띵작","띵곡","띵문"}'::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Golden quote / wise words (meme spelling)"}, {"lang": "🇯🇵 JA", "text": "名言(野民正音表記)"}, {"lang": "🇨🇳 ZH", "text": "名言(谐形网络写法)"}, {"lang": "🇻🇳 VI", "text": "Danh ngon (cach viet che chu)"}, {"lang": "🇪🇸 ES", "text": "Frase celebre (grafia meme)"}, {"lang": "🇩🇪 DE", "text": "Goldenes Zitat (Meme-Schreibweise)"}]'::jsonb),
('580', '샤방샤방', 'Sya-Bang-Sya-Bang', 'outdated-slang', null, '화사하고 예뻐서 빛나 보이는 모양', '{"de": "Strahlend hübsch, wie funkelnd", "en": "Radiantly pretty, as if sparkling", "es": "Radiante y bonito, como si brillara", "ja": "華やかできれいで、輝いて見える様子", "vi": "Tươi tắn xinh đẹp như đang tỏa sáng"}'::jsonb, '[샤방샤방]', '[{"definition": "사람이나 물건이 화사하고 예뻐 빛나 보이는 모양. 주로 ''샤방샤방하다'' 꼴로 쓴다. 2000년대에 크게 유행했고 지금은 그 시절 말투로 들린다.", "definition_i18n": {"de": "Beschreibt jemanden oder etwas als strahlend, hübsch und beinahe funkelnd; meist als 샤방샤방하다. In den 2000ern riesig, heute klingt es nach dieser Zeit.", "en": "Describes a person or thing as bright, pretty and almost sparkling; usually used as 샤방샤방하다. A huge 2000s word that now sounds of its era.", "es": "Describe a alguien o algo como luminoso, bonito y casi brillante; se usa sobre todo como 샤방샤방하다. Arrasó en los 2000 y hoy suena a esa época.", "ja": "人や物が華やかできれいで輝いて見える様子。主に「샤방샤방하다」の形で使う。2000年代に大流行し、今は当時の言い回しに聞こえる。", "vi": "Tả người hay vật tươi sáng, xinh đẹp như đang lấp lánh; thường dùng dạng 샤방샤방하다. Rất thịnh thập niên 2000, nay nghe ra chất thời đó."}, "examples": [{"de": "Mein Make-up sitzt heute wohl gut — mein Gesicht strahlt richtig.", "eng": "My makeup must have gone on well today — my face is positively glowing.", "es": "Hoy me ha cuajado bien el maquillaje, tengo la cara radiante.", "ja": "今日メイクのりがいいみたい、顔がシャバンシャバン", "kor": "오늘 화장 잘 먹었나 봐, 얼굴이 샤방샤방하다", "vi": "Chắc hôm nay lớp trang điểm ăn da, mặt cứ sáng bừng."}], "type": "부사/형용사"}, {"definition": "자전거 동호인 사이에서는 경치를 보며 아주 느긋하게 달리는 주행을 가리키기도 한다. 위의 일반적인 뜻과는 별개로 쓰이는 은어다.", "definition_i18n": {"de": "Unter Radfahrern bezeichnet es auch sehr gemütliches Fahren mit Blick auf die Landschaft — eine eigene Szene-Bedeutung neben der allgemeinen.", "en": "Among cyclists it also means riding very slowly and leisurely while enjoying the scenery — a separate club-jargon sense from the general one above.", "es": "Entre ciclistas también designa rodar muy despacio disfrutando del paisaje: una acepción de jerga distinta de la general.", "ja": "自転車愛好家の間では、景色を眺めながらとてもゆっくり走る走行を指すこともある。上の一般的な意味とは別に使われる隠語。", "vi": "Trong giới đạp xe, nó còn chỉ kiểu đạp thật thong thả ngắm cảnh — nghĩa lóng riêng, khác nghĩa chung ở trên."}, "examples": [{"de": "Heute ohne Zeitdruck — wir cruisen einfach.", "eng": "Forget the time today, let us just cruise.", "es": "Hoy olvidemos el crono y vamos tranquilos.", "ja": "今日はタイムは気にせずのんびり流そう", "kor": "오늘은 기록 신경 쓰지 말고 샤방샤방으로 가자", "vi": "Hôm nay khỏi lo thành tích, mình đạp thong thả thôi."}], "type": "명사"}]'::jsonb, '어원은 확정되지 않았다. 2000년대 인터넷에서 퍼진 의태어라는 설이 널리 알려져 있고, 이후 대중가요 가사에까지 쓰이며 더 퍼졌다는 설명이 붙는다. 자전거 동호인 은어로 쓰이는 갈래가 언제 갈라져 나왔는지도 확인되지 않는다.', '{"de": "Die Herkunft ist ungeklärt. Gängig ist die Darstellung, es habe sich in den 2000ern als lautmalerisch wirkendes Wort im koreanischen Netz verbreitet und sei durch Songtexte weitergetragen worden. Wann sich der Rad-Jargon abspaltete, ist ebenfalls unbelegt.", "en": "The etymology is unsettled. The common account is that it spread as an onomatopoeic-style word on the 2000s Korean internet and was carried further when it turned up in pop lyrics. When the cycling-jargon branch split off is also unverified.", "es": "La etimología no está fijada. La versión habitual es que se difundió como palabra expresiva en internet en los 2000 y llegó más lejos al aparecer en letras de canciones. Tampoco se sabe cuándo se separó la acepción ciclista.", "ja": "語源は未確定。2000年代の韓国のネットで広まった擬態語だという説が知られ、その後歌謡曲の歌詞にも使われてさらに広まったと説明される。自転車愛好家の隠語としての用法がいつ分かれたのかも不明。", "vi": "Từ nguyên chưa xác định. Cách giải thích phổ biến là nó lan như một từ tượng hình trên mạng Hàn thập niên 2000, rồi đi xa hơn khi xuất hiện trong lời bài hát. Nhánh nghĩa của dân đạp xe tách ra khi nào cũng chưa rõ."}'::jsonb, '주로 외모나 차림새를 칭찬할 때 ''샤방샤방하다''로 쓴다. 지금 쓰면 2000년대를 떠올리게 하는 말투라, 젊은 층 대화보다는 농담이나 추억 삼아 나온다.', '{"de": "Meist als 샤방샤방하다, um Aussehen oder Outfit zu loben. Heute ruft es die 2000er auf und taucht eher als Scherz oder Rückblick auf.", "en": "Mostly used as 샤방샤방하다 to compliment someone''s looks or outfit. Today it flags the 2000s, so it shows up more as a joke or a throwback than in everyday young-adult talk.", "es": "Se usa sobre todo como 샤방샤방하다 para halagar el aspecto o la ropa de alguien. Hoy evoca los 2000, así que aparece más como broma o guiño nostálgico.", "ja": "主に外見や装いを褒めるとき「샤방샤방하다」の形で使う。今使うと2000年代を思わせる言い回しなので、若者の会話より冗談や懐かしさとして出てくる。", "vi": "Chủ yếu dùng dạng 샤방샤방하다 để khen ngoại hình hay trang phục. Giờ nó gợi nhớ thập niên 2000 nên thường xuất hiện như câu đùa hay hoài niệm hơn là trong hội thoại của giới trẻ."}'::jsonb, '{"얼짱","훈남","과즙상"}'::text[], null, 0, 0, '[{"lang": "🇺🇸 EN", "text": "Glowing / radiant, sparkly-pretty"}, {"lang": "🇯🇵 JA", "text": "キラキラしてきれい"}, {"lang": "🇨🇳 ZH", "text": "光彩照人、闪闪发亮"}, {"lang": "🇻🇳 VI", "text": "Rạng rỡ, lấp lánh xinh"}, {"lang": "🇪🇸 ES", "text": "Radiante, resplandeciente"}, {"lang": "🇩🇪 DE", "text": "Strahlend hübsch"}]'::jsonb),
('581', '숲튽훈', 'Sup-teun-hun', 'yaminjeongeum', null, '이름의 한자를 닮은 한글로 바꿔 적은 김장훈의 별명', '{"de": "Kim Jang-hoon, dessen Namens-Hanja durch ahnliches Hangul ersetzt sind", "en": "Kim Jang-hoon, his name''s hanja swapped for look-alike Hangul", "es": "Kim Jang-hoon, con los hanja de su nombre cambiados por hangul parecido", "ja": "名前の漢字を似たハングルに替えたキム・ジャンフンのあだ名", "vi": "Kim Jang-hoon, chu Han trong ten duoc doi thanh Hangul trong giong"}'::jsonb, '[숩튼훈]', '[{"definition": "가수 김장훈을 가리키는 인터넷 별명. 이름을 한자로 쓰면 金長勳인데, 金이 한글 ''숲''과, 長이 ''튽''과 모양이 닮았다는 점을 이용해 ''숲튽훈''으로 바꿔 적는다. 한글끼리 바꾸는 흔한 야민정음과 달리 한자와 한글을 넘나드는 유형이라 교과서처럼 인용되는 사례다. 만들어진 배경은 호의적이지 않아, 그의 여러 구설수를 비꼬는 맥락에서 쓰였다.", "definition_i18n": {"de": "Ein Internet-Spitzname fur den Sanger Kim Jang-hoon. In Hanja heisst er 金長勳, und weil 金 dem Hangul 숲 und 長 dem 튽 ahnelt, wird er 숲튽훈 geschrieben. Anders als ubliches Yaminjeongeum, das Hangul gegen Hangul tauscht, wechselt dieses zwischen Hanja und Hangul - daher gilt es als Lehrbuchfall. Die Absicht war nicht freundlich: Man stichelte damit gegen ihn wegen mehrerer Skandale.", "en": "An internet nickname for the singer Kim Jang-hoon. Written in hanja his name is 金長勳, and because 金 resembles the Hangul 숲 while 長 resembles 튽, it gets respelled 숲튽훈. Unlike ordinary Yaminjeongeum, which swaps Hangul for Hangul, this one crosses between hanja and Hangul, which is why it is cited as the textbook case. The intent behind it was not friendly - it was used to needle him over a string of controversies.", "es": "Apodo de internet del cantante Kim Jang-hoon. En hanja su nombre es 金長勳, y como 金 se parece al hangul 숲 y 長 a 튽, se reescribe 숲튽훈. A diferencia del yaminjeongeum corriente, que cambia hangul por hangul, este cruza entre hanja y hangul, por eso se cita como el caso de manual. Su origen no fue amable: se uso para pincharle por una serie de polemicas.", "ja": "歌手キム・ジャンフンを指すネットのあだ名。漢字で書くと金長勳だが、金がハングルの「숲」に、長が「튽」に形が似ていることを使って「숲튽훈」と書き替える。ハングル同士を替える普通の野民正音と違い、漢字とハングルをまたぐ型なので教科書のように引用される。成り立ちは好意的ではなく、彼の度重なる物議を皮肉る文脈で使われた。", "vi": "Biet danh tren mang cua ca si Kim Jang-hoon. Viet bang chu Han ten anh la 金長勳, va vi 金 giong chu Hangul 숲 con 長 giong 튽, nen duoc viet lai thanh 숲튽훈. Khac voi yaminjeongeum thong thuong doi Hangul sang Hangul, tu nay bac cau giua chu Han va Hangul, nen duoc dan nhu vi du kinh dien. Y do phia sau khong thien chi - no duoc dung de xoay anh ve loat lum xum."}, "examples": [{"de": "Ich habe lange gelacht, als ich kapierte, dass Sup-teun-hun Kim Jang-hoon ist.", "eng": "I laughed for a while once I got that Sup-teun-hun is Kim Jang-hoon.", "es": "Me rei un buen rato al entender que Sup-teun-hun es Kim Jang-hoon.", "ja": "スプトゥンフンがキム・ジャンフンだと分かってしばらく笑った。", "kor": "숲튽훈이 김장훈인 거 알고 한참 웃었네.", "vi": "Hieu ra Sup-teun-hun la Kim Jang-hoon xong tui cuoi mot luc lau."}, {"de": "金 als 숲 lesen - das ist der Hanja-Typ des Yaminjeongeum.", "eng": "Reading 金 as 숲 - that is the hanja type of Yaminjeongeum.", "es": "Leer 金 como 숲: ese es el tipo hanja del yaminjeongeum.", "ja": "金を숲と読むのが野民正音の漢字型だよ。", "kor": "金을 숲으로 읽는 게 야민정음 한자형이야.", "vi": "Doc 金 thanh 숲 - do la kieu chu Han cua yaminjeongeum."}], "type": "명사"}]'::jsonb, '야민정음의 여러 방식 중 한자를 끌어다 쓰는 유형이다. 金(쇠 금)을 한글 ''숲''으로, 長(길 장)을 ''튽''으로 바꾸고 이름 끝 글자 ''훈''은 그대로 두어 ''숲튽훈''이 된다. 2010년대 중후반 김장훈이 여러 구설수에 오르자 이를 비판하는 누리꾼들이 별명으로 굳혔고, 언론이 별명의 뜻을 설명하는 기사를 낼 만큼 퍼졌다.', '{"de": "Das ist der Hanja-Zweig des Yaminjeongeum. 金 (Gold, gelesen gim) wird zum Hangul 숲, 長 (lang, gelesen jang) zu 튽, das abschliessende 훈 bleibt - ergibt 숲튽훈. Mitte bis Ende der 2010er verfestigte es sich als Spitzname, als Kim Jang-hoon in Skandale geriet und Kritiker es online aufgriffen; es verbreitete sich so weit, dass Zeitungen erklarende Artikel dazu brachten.", "en": "This is the hanja branch of Yaminjeongeum. 金 (gold, read gim) becomes the Hangul 숲, 長 (long, read jang) becomes 튽, and the final 훈 stays put, giving 숲튽훈. It hardened into a nickname in the mid-to-late 2010s as Kim Jang-hoon ran into repeated controversies and critics online picked it up; it spread far enough that newspapers ran explainers on what the nickname meant.", "es": "Es la rama hanja del yaminjeongeum. 金 (oro, gim) pasa al hangul 숲, 長 (largo, jang) a 튽, y el 훈 final se queda, dando 숲튽훈. Cuajo como apodo a mediados y finales de los 2010, cuando Kim Jang-hoon encadeno polemicas y los criticos en linea lo adoptaron; se extendio tanto que los diarios publicaron explicaciones del apodo.", "ja": "野民正音の方式のうち漢字を引いてくる型。金(かね・キム)をハングルの「숲」に、長(ながい・ジャン)を「튽」に替え、名の最後の「훈」はそのままにして「숲튽훈」となる。2010年代半ば〜後半にキム・ジャンフンが度々物議を醸す中、批判するネットユーザーがあだ名として定着させ、メディアが意味を説明する記事を出すほど広まった。", "vi": "Day la nhanh chu Han cua yaminjeongeum. 金 (vang, doc gim) thanh chu Hangul 숲, 長 (dai, doc jang) thanh 튽, con chu 훈 cuoi giu nguyen, ra 숲튽훈. No dong lai thanh biet danh giua va cuoi thap nien 2010 khi Kim Jang-hoon lien tuc vuong lum xum va cu dan mang chi trich dung no; no lan rong den muc bao chi phai dang bai giai thich nghia biet danh."}'::jsonb, '실존 인물을 놀리는 데서 나온 말이라 그 사람 이야기를 할 때 쓰면 편을 정하는 셈이 된다. 배우려는 사람 입장에서는 ''한자를 닮은 한글로 바꾸는 유형이 이런 것''이라는 예로 알아 두는 정도가 적당하다. 표기는 ''숲튽훈''과 ''숲튼훈''이 섞여 쓰이는데 같은 말이다.', '{"de": "Da es als Spott uber eine reale Person begann, bezieht man mit seiner Verwendung Position. Lernende merken es sich am besten als Beispiel dafur, wie der Hanja-Tausch funktioniert. Die Schreibungen 숲튽훈 und 숲튼훈 kursieren beide und meinen dasselbe.", "en": "Because it began as mockery of a real person, using it about him takes a side. For a learner it is best kept as an illustration of how the hanja-swap type works. The spellings 숲튽훈 and 숲튼훈 both circulate and mean the same thing.", "es": "Como nacio de la burla a una persona real, usarlo sobre el implica tomar partido. Para quien aprende, conviene quedarse con el ejemplo de como funciona el cambio hanja-hangul. Circulan las grafias 숲튽훈 y 숲튼훈 y significan lo mismo.", "ja": "実在の人物をからかうところから出た語なので、本人の話で使うと立場を取ることになる。学ぶ側としては「漢字に似たハングルへ替える型はこういうもの」という例として知っておく程度がよい。表記は「숲튽훈」と「숲튼훈」が混在するが同じ語。", "vi": "Vi no bat dau tu viec che gieu mot nguoi that, dung no khi noi ve anh ay la chon phe. Voi nguoi hoc, tot nhat giu no nhu vi du minh hoa kieu doi chu Han sang Hangul. Hai cach viet 숲튽훈 va 숲튼훈 deu luu hanh va cung nghia."}'::jsonb, '{"세종머앟","티本","롬곡"}'::text[], '{"숲튼훈"}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Kim Jang-hoon (hanja-swap meme nickname)"}, {"lang": "🇯🇵 JA", "text": "キム・ジャンフン(漢字置換のあだ名)"}, {"lang": "🇨🇳 ZH", "text": "金长勋(汉字谐形绰号)"}, {"lang": "🇻🇳 VI", "text": "Kim Jang-hoon (biet danh doi chu Han)"}, {"lang": "🇪🇸 ES", "text": "Kim Jang-hoon (apodo por cambio de hanja)"}, {"lang": "🇩🇪 DE", "text": "Kim Jang-hoon (Spitzname durch Hanja-Tausch)"}]'::jsonb);

commit;
